package com.example.sumayerestaurant.ui.finance;
import android.app.*;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.sumayerestaurant.data.api.RetrofitClient;import com.example.sumayerestaurant.data.local.TokenManager;import com.example.sumayerestaurant.data.model.*;import java.time.LocalDate;import java.util.*;import retrofit2.*;
public class ExpenseActivity extends AppCompatActivity{private Long branch;private Spinner categories,method;private EditText amount,description,date,notes;@Override public void onCreate(Bundle b){super.onCreate(b);User u=new TokenManager(this).getUser();branch=(u==null||u.getBranchId()==null)?1L:u.getBranchId();setTitle("Rekodi Gharama");LinearLayout root=new LinearLayout(this);root.setPadding(28,28,28,28);root.setOrientation(LinearLayout.VERTICAL);categories=new Spinner(this);root.addView(categories);amount=f("Kiasi cha TZS");description=f("Maelezo ya gharama");date=f("Tarehe (YYYY-MM-DD)");date.setText(LocalDate.now().toString());method=new Spinner(this);method.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"CASH","MOBILE_MONEY","CARD","BANK","OTHER"}));notes=f("Maelezo ya ziada (si lazima)");root.addView(amount);root.addView(description);root.addView(date);root.addView(method);root.addView(notes);Button save=new Button(this);save.setText("Thibitisha na Hifadhi");root.addView(save);setContentView(root);save.setOnClickListener(v->confirm());loadCategories();}private EditText f(String hint){EditText e=new EditText(this);e.setHint(hint);e.setMinHeight(84);return e;}private void loadCategories(){if(branch==null)return;RetrofitClient.getApiService(this).getExpenseCategories(branch).enqueue(new Callback<List<ExpenseCategory>>(){public void onResponse(Call<List<ExpenseCategory>>c,Response<List<ExpenseCategory>>r){if(r.isSuccessful()&&r.body()!=null)categories.setAdapter(new ArrayAdapter<>(ExpenseActivity.this,android.R.layout.simple_spinner_dropdown_item,r.body()));else msg("Imeshindikana kupakia makundi.");}public void onFailure(Call<List<ExpenseCategory>>c,Throwable t){msg("Hakuna mtandao.");}});}private void confirm(){if(categories.getSelectedItem()==null||amount.getText().toString().isEmpty()||description.getText().toString().isEmpty()){msg("Chagua kundi, kiasi na maelezo.");return;}new AlertDialog.Builder(this).setMessage("Kiasi: TZS "+amount.getText()+"\nKundi: "+categories.getSelectedItem()+"\nTarehe: "+date.getText()).setNegativeButton("Ghairi",null).setPositiveButton("Hifadhi",(d,w)->save()).show();}private void save(){try{ExpenseCategory c=(ExpenseCategory)categories.getSelectedItem();Map<String,Object>x=new HashMap<>();x.put("categoryId",c.getId());x.put("amount",amount.getText().toString());x.put("description",description.getText().toString());x.put("expenseDate",date.getText().toString());x.put("paymentMethod",method.getSelectedItem().toString());x.put("notes",notes.getText().toString());RetrofitClient.getApiService(this).createExpense(branch,x).enqueue(new Callback<Object>(){public void onResponse(Call<Object>c,Response<Object>r){if(r.isSuccessful()){msg("Gharama imehifadhiwa.");finish();}else msg("Imeshindikana kuhifadhi. Hakiki taarifa.");}public void onFailure(Call<Object>c,Throwable t){msg("Hakuna mtandao.");}});}catch(Exception e){msg("Weka tarehe na kiasi sahihi.");}}private void msg(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
